// AntiChatKit: one root package, one module per component group (architecture.md §1.1, §2).
// Dependency edges = architecture.md §3 (PRD §6.1 rule 2). Pins: architecture.md §9.3, tools/ci/pins.json.
// OsaurusVendored = the Osaurus extraction closure (M0.T02/T14, upstream.md); its source list is
// generated by `tools/vendor-sync materialize osaurus` from Vendor/osaurus-allowlist.tsv.
import PackageDescription

// Swift 6 language mode implies complete strict-concurrency checking (SE-0337/SE-0414).
let ours: [SwiftSetting] = [
    .swiftLanguageMode(.v6),
]

func module(
    _ group: String,
    deps: [Target.Dependency] = [],
    resources: [Resource]? = nil
) -> Target {
    .target(
        name: "AntiChat\(group)",
        dependencies: deps,
        path: "Packages/\(group)/Sources/AntiChat\(group)",
        resources: resources,
        swiftSettings: ours
    )
}

func tests(_ group: String, name: String? = nil, extra: [Target.Dependency] = []) -> Target {
    let n = name ?? "AntiChat\(group)Tests"
    return .testTarget(
        name: n,
        dependencies: [.target(name: "AntiChat\(group)")] + extra,
        path: "Packages/\(group)/Tests/\(n)",
        swiftSettings: ours
    )
}

